from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the available rectangular tiles exactly covers an H×W grid."""
    if h <= 0 or w <= 0 or n < 0 or n > len(tiles):
        return False

    # Only the first n tiles are available, as specified by n.
    sizes = tiles[:n]
    areas = [a * b for a, b in sizes]
    target = h * w
    full_row = (1 << w) - 1

    # A subset of the unused tiles must have exactly the area of the remaining cells.
    subset_sums = [0] * (1 << n)
    for mask in range(1, 1 << n):
        bit = mask & -mask
        i = bit.bit_length() - 1
        subset_sums[mask] = subset_sums[mask ^ bit] + areas[i]

    @lru_cache(None)
    def search(rows: Tuple[int, ...], used: int) -> bool:
        remaining = target - sum(row.bit_count() for row in rows)
        if remaining == 0:
            return True

        unused = ((1 << n) - 1) ^ used
        possible_areas = {subset_sums[subset] for subset in range(1 << n)
                          if subset & used == 0}
        if remaining not in possible_areas:
            return False

        # The first uncovered cell is forced to be the top-left cell of its tile:
        # any earlier cell is already covered, so extending left or upward would overlap.
        for r, row in enumerate(rows):
            if row != full_row:
                c = 0
                while row & (1 << c):
                    c += 1
                break

        for i, (a, b) in enumerate(sizes):
            bit = 1 << i
            if used & bit or areas[i] > remaining:
                continue
            orientations = {(a, b), (b, a)}
            for height, width in orientations:
                if r + height > h or c + width > w:
                    continue
                row_bits = ((1 << width) - 1) << c
                if any(rows[rr] & row_bits for rr in range(r, r + height)):
                    continue
                updated = list(rows)
                for rr in range(r, r + height):
                    updated[rr] |= row_bits
                if search(tuple(updated), used | bit):
                    return True
        return False

    return search((0,) * h, 0)

