MOD = 998244353


def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid ..."""
    # Use the smaller dimension as the transfer width.
    if H <= W:
        rows, width = W, H
        cells = [[grid[r][c] for r in range(H)] for c in range(W)]
    else:
        rows, width = H, W
        cells = [list(row) for row in grid]

    allowed_rows = []
    for row in cells:
        allowed = []
        for ch in row:
            allowed.append((1, 2, 3) if ch == "?" else (int(ch),))
        allowed_rows.append(allowed)

    def enumerate_row(allowed, previous=None):
        assignment = [0] * width

        def visit(col):
            if col == width:
                yield tuple(assignment)
                return
            for color in allowed[col]:
                if col and assignment[col - 1] == color:
                    continue
                if previous is not None and previous[col] == color:
                    continue
                assignment[col] = color
                yield from visit(col + 1)

        yield from visit(0)

    dp = {state: 1 for state in enumerate_row(allowed_rows[0])}
    for r in range(1, rows):
        next_dp = {}
        allowed = allowed_rows[r]
        for previous, ways in dp.items():
            for state in enumerate_row(allowed, previous):
                next_dp[state] = (next_dp.get(state, 0) + ways) % MOD
        dp = next_dp
        if not dp:
            return 0
    return sum(dp.values()) % MOD

