from functools import lru_cache
from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified 3x3 tic-tac-toe game with optimal play."""
    values = tuple(value for row in grid for value in row)
    lines = []
    for i in range(3):
        lines.append(sum(1 << (3 * i + j) for j in range(3)))
        lines.append(sum(1 << (3 * j + i) for j in range(3)))
    lines.extend((0b100010001, 0b001010100))

    @lru_cache(None)
    def solve(red: int, blue: int) -> int:
        # Return +1 if Takahashi eventually wins, -1 if Aoki wins.
        taken = red | blue
        turn = taken.bit_count()  # Takahashi moves on even turns.
        for line in lines:
            if red & line == line:
                return 1
            if blue & line == line:
                return -1

        if taken == 0b111111111:
            red_score = sum(values[i] for i in range(9) if red & (1 << i))
            blue_score = sum(values[i] for i in range(9) if blue & (1 << i))
            return 1 if red_score > blue_score else -1

        best = -2 if turn % 2 == 0 else 2
        for i in range(9):
            bit = 1 << i
            if taken & bit:
                continue
            if turn % 2 == 0:
                result = solve(red | bit, blue)
                best = max(best, result)
            else:
                result = solve(red, blue | bit)
                best = min(best, result)
        return best

    return "Takahashi" if solve(0, 0) == 1 else "Aoki"

