def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of edge-adjacent tiles between the two points."""
    from heapq import heappop, heappush

    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i - j) % 2 == 0

    def lane(i, j, x, y):
        return y % K if horizontal(i, j) else x % K

    sl = lane(si, sj, S_x, S_y)
    tl = lane(ti, tj, T_x, T_y)
    if (si, sj, sl) == (ti, tj, tl):
        return 0

    # Only endpoint lanes and block-edge lanes can affect a shortest route.
    lanes = sorted({0, K - 1, sl, tl})
    manhattan = abs(ti - si) + abs(tj - sj)
    if manhattan > 400:
        return manhattan

    lo_i, hi_i = min(si, ti) - 2, max(si, ti) + 2
    lo_j, hi_j = min(sj, tj) - 2, max(sj, tj) + 2
    start, goal = (si, sj, sl), (ti, tj, tl)
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == goal:
            return d
        i, j, k = state
        for q in lanes:
            if q != k:
                nxt = (i, j, q)
                nd = d + abs(q - k)
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))

        for axis, step in (("x", -1), ("x", 1), ("y", -1), ("y", 1)):
            ni = i + step if axis == "x" else i
            nj = j + step if axis == "y" else j
            if not (lo_i <= ni <= hi_i and lo_j <= nj <= hi_j):
                continue
            src_h, dst_h = horizontal(i, j), horizontal(ni, nj)
            required_src = required_dst = None
            if axis == "x":
                if src_h:
                    required_dst = 0 if step > 0 else K - 1
                else:
                    required_src = K - 1 if step > 0 else 0
            else:
                if src_h:
                    required_src = K - 1 if step > 0 else 0
                else:
                    required_dst = 0 if step > 0 else K - 1
            if required_src is not None and k != required_src:
                continue
            targets = [required_dst] if required_dst is not None else lanes
            for q in targets:
                nxt = (ni, nj, q)
                nd = d + 1
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))

    return manhattan

from functools import lru_cache
from typing import List


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, there is a knight at position (kx, ky) and pawns at the given positions.
    Alice and Bob alternate capturing remaining pawns. Alice maximizes the total moves;
    Bob minimizes them. The knight may pass uncaptured pawns.
    """
    points = [(kx, ky)] + [tuple(p) for p in positions]
    n = len(positions)

    def knight_distance(a: tuple, b: tuple) -> int:
        dx, dy = abs(a[0] - b[0]), abs(a[1] - b[1])
        x, y = max(dx, dy), min(dx, dy)
        # Exact shortest distance on an unbounded board.
        distance = max((x + 1) // 2, (x + y + 2) // 3)
        while (distance + x + y) % 2:
            distance += 1
        if x == 1 and y == 0:
            return 3
        if x == 2 and y == 2:
            return 4
        return distance

    distances = [[knight_distance(a, b) for b in points] for a in points]

    @lru_cache(maxsize=None)
    def best(remaining: int, current: int) -> int:
        if remaining == 0:
            return 0
        alice_turn = (n - remaining.bit_count()) % 2 == 0
        choices = []
        bits = remaining
        while bits:
            bit = bits & -bits
            pawn = bit.bit_length() - 1
            choices.append(distances[current][pawn + 1] +
                           best(remaining ^ bit, pawn + 1))
            bits ^= bit
        return (max if alice_turn else min)(choices)

    return best((1 << n) - 1, 0)

from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count length-M sequences whose product n<=N has sigma(n) divisible by 3."""
    if N < 1 or M < 1:
        return 0
    if N == 1:
        return 0

    # The number of ordered ways to distribute each prime's exponent among M
    # factors is C(M+e-1,e).
    max_e = 33  # 2**33 > 10**10
    ways = [1] + [0] * max_e
    for e in range(1, max_e + 1):
        ways[e] = ways[e - 1] * (M + e - 1) // e % MOD

    # Sieve enough primes for all small-prime recursion and Lehmer's pi.
    limit = 100000
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * ((limit - start) // p + 1)
    primes = [i for i in range(2, limit + 1) if sieve[i]]
    pi_small = [0] * (limit + 1)
    cnt = 0
    for i in range(limit + 1):
        if sieve[i]:
            cnt += 1
        pi_small[i] = cnt

    @lru_cache(maxsize=None)
    def phi(x, s):
        if s == 0:
            return x
        if s == 1:
            return x - x // 2
        if primes[s - 1] >= x:
            return 1
        return phi(x, s - 1) - phi(x // primes[s - 1], s - 1)

    @lru_cache(maxsize=None)
    def lehmer_pi(x):
        if x <= limit:
            return pi_small[x]
        a = lehmer_pi(isqrt(isqrt(x)))
        b = lehmer_pi(isqrt(x))
        c = lehmer_pi(int(round(x ** (1 / 3))))
        # Correct floating cube-root rounding near integer cubes.
        while (c + 1) ** 3 <= x:
            c += 1
        while c ** 3 > x:
            c -= 1
        total = phi(x, a) + ((b + a - 2) * (b - a + 1)) // 2
        for i in range(a, b):
            w = x // primes[i]
            total -= lehmer_pi(w)
            if i < c:
                lim = lehmer_pi(isqrt(w))
                for j in range(i, lim):
                    total -= lehmer_pi(w // primes[j]) - j
        return total

    # Sum a multiplicative weight over integers whose prime factors are at
    # least primes[start]. For primes above sqrt(x), only the exponent-one
    # term can occur, so those contributions are counted with Lehmer's pi.
    def rough_sum(local_weights):
        @lru_cache(maxsize=None)
        def rec(x, start):
            if x <= 1:
                return 1
            root = isqrt(x)
            # For p > sqrt(x), the remaining cofactor must be 1.
            first_large = max(start, pi_small[root])
            result = 1 + local_weights[1] * (lehmer_pi(x) - lehmer_pi(root))
            # Primes p > root are always included above. For p <= root,
            # enumerate their exponent and recursively choose larger primes.
            for idx in range(start, pi_small[root]):
                p = primes[idx]
                q = x // p
                e = 1
                power = p
                while power <= x:
                    coeff = local_weights[e]
                    if coeff:
                        result += coeff * rec(x // power, idx + 1)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
            # Remove primes <= root which are below the permitted start only
            # by construction none; first_large documents the boundary.
            return result % MOD
        return rec

    all_weights = ways
    good_weights = [0] * (max_e + 1)
    good_weights[0] = 1
    for p in (2, 3, 5):
        pass
    # For a prime p != 3:
    #   p=1 mod 3: sigma(p^e) is 0 mod 3 iff e=2 mod 3.
    #   p=2 mod 3: sigma(p^e) is 0 mod 3 iff e is odd.
    # For p=3 the local sigma is always 1 mod 3.
    # The recurrence permits different weights by prime type. Compute the
    # total sum as the all-weight sum minus the sum with no zero local factor.
    # A three-class recurrence is used below for the latter.
    total = rough_sum(all_weights)(N, 0)

    # Recurrence for the no-good-factor contribution, with prime type weights.
    @lru_cache(maxsize=None)
    def no_bad(x, start):
        if x <= 1:
            return 1
        root = isqrt(x)
        result = 1 + ways[1] * (lehmer_pi(x) - lehmer_pi(root))
        for idx in range(start, pi_small[root]):
            p = primes[idx]
            q = x // p
            if p > root:
                continue
            if p == 3:
                weights = ways
            elif p % 3 == 1:
                weights = [ways[e] if e % 3 != 2 else 0 for e in range(max_e + 1)]
            else:
                weights = [ways[e] if e % 2 == 0 else 0 for e in range(max_e + 1)]
            power = p
            e = 1
            while power <= x:
                coeff = weights[e]
                if coeff:
                    result += coeff * no_bad(x // power, idx + 1)
                e += 1
                if power > x // p:
                    break
                power *= p
        return result % MOD

    # The no_bad recursion's exponent weights depend on the current prime,
    # whereas the prime-tail term (exponent one) is uniform.
    return (total - no_bad(N, 0)) % MOD

def count_in_degree_sequences(n: int, s: str) -> int:
    """ Given a positive integer n and a string s of length n consisting of '0' and '1',
    construct a graph G with (n+1) vertices numbered 0 to n, with the following edges:
    - For each i from 0 to n-1, there's an edge between vertices i and (i+1) mod n
    - For each i from 0 to n-1, there's an edge between vertices i and n if s[i] == '1'

    Create a directed graph G' by assigning a direction to each edge of G.
    For each vertex i, let d_i be its in-degree in G'.

    Return the number of distinct sequences (d_0, d_1, ..., d_n) that can be obtained,
    modulo 998244353.

    Args:
        n: A positive integer (3 <= n <= 10^6)
        s: A string of length n consisting only of '0' and '1'

    Returns:
        The number of distinct in-degree sequences modulo 998244353

    >>> count_in_degree_sequences(3, '010')
    14
    >>> count_in_degree_sequences(20, '00001100111010100101')
    261339902
    """
    mod = 998244353

    # A relation is a 2x2 Boolean matrix, encoded row-major in four bits.
    # At position i, the prior and next cycle-edge directions are the row
    # and column states. If they are x and y, the cycle contribution is
    # 1 + x - y. A spoke, when present, can add either zero or one.
    labels = {}
    for spoke in (0, 1):
        by_degree = {}
        for degree in range(4):
            matrix = 0
            for before in (0, 1):
                for after in (0, 1):
                    base = 1 + before - after
                    if degree - base in ((0, 1) if spoke else (0,)):
                        matrix |= 1 << (2 * before + after)
            if matrix:
                by_degree[degree] = matrix
        labels[spoke] = tuple(by_degree.values())

    compose = [[0] * 16 for _ in range(16)]
    for first in range(16):
        for second in range(16):
            result = 0
            for a in (0, 1):
                for b in (0, 1):
                    if first & (1 << (2 * a + b)):
                        for c in (0, 1):
                            if second & (1 << (2 * b + c)):
                                result |= 1 << (2 * a + c)
            compose[first][second] = result

    # Count words by their resulting relation. The sequence is realizable by
    # a cyclic orientation exactly when this relation has a diagonal entry.
    counts = [0] * 16
    counts[9] = 1  # identity relation: the cycle starts in either state
    for bit in s:
        transitions = labels[bit == "1"]
        following = [0] * 16
        for relation, ways in enumerate(counts):
            if ways:
                for transition in transitions:
                    state = compose[relation][transition]
                    following[state] = (following[state] + ways) % mod
        counts = following

    return sum(counts[mask] for mask in range(16) if mask & 9) % mod

from functools import lru_cache
from math import isqrt

MOD = 998244353


def count_good_sequences(N: int, M: int) -> int:
    """Count sequences whose product n<=N has sum of divisors divisible by 3."""
    if N <= 1:
        return 0

    # For n=prod(p**e), the number of ordered M-tuples with product n is
    # prod C(M+e-1,e).
    max_e = 33
    ways = [1] + [0] * max_e
    for e in range(1, max_e + 1):
        ways[e] = ways[e - 1] * (M + e - 1) % MOD * pow(e, MOD - 2, MOD) % MOD

    limit = 100000
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b"\x00" * ((limit - start) // p + 1)
    primes = [i for i in range(2, limit + 1) if sieve[i]]
    pi_small = [0] * (limit + 1)
    count = 0
    for i in range(limit + 1):
        if sieve[i]:
            count += 1
        pi_small[i] = count

    @lru_cache(maxsize=None)
    def phi(x, s):
        if s == 0:
            return x
        if s == 1:
            return x - x // 2
        if primes[s - 1] >= x:
            return 1
        return phi(x, s - 1) - phi(x // primes[s - 1], s - 1)

    @lru_cache(maxsize=None)
    def prime_pi(x):
        if x <= limit:
            return pi_small[x]
        a = prime_pi(isqrt(isqrt(x)))
        b = prime_pi(isqrt(x))
        c = prime_pi(int(round(x ** (1 / 3))))
        while (c + 1) ** 3 <= x:
            c += 1
        while c ** 3 > x:
            c -= 1
        result = phi(x, a) + (b + a - 2) * (b - a + 1) // 2
        for i in range(a, b):
            w = x // primes[i]
            result -= prime_pi(w)
            if i < c:
                for j in range(i, prime_pi(isqrt(w))):
                    result -= prime_pi(w // primes[j]) - j
        return result

    def unrestricted(weights):
        @lru_cache(maxsize=None)
        def rec(x, start):
            if x <= 1:
                return 1
            root = isqrt(x)
            # Exponent-one prime factors above sqrt(x) have no cofactor left.
            first_tail = max(pi_small[root], start)
            lower = primes[first_tail - 1] if first_tail > pi_small[root] else root
            result = 1 + weights[1] * (prime_pi(x) - prime_pi(lower))
            for idx in range(start, pi_small[root]):
                p = primes[idx]
                power = p
                e = 1
                while power <= x:
                    coeff = weights[e]
                    if coeff:
                        result += coeff * rec(x // power, idx + 1)
                    e += 1
                    if power > x // p:
                        break
                    power *= p
            return result % MOD
        return rec

    all_sum = unrestricted(ways)(N, 0)

    # A local divisor sum is zero modulo 3 for p=1 mod 3 and e=2 mod 3,
    # or p=2 mod 3 and odd e. Such an integer is good iff at least one
    # prime-power factor has this property.
    @lru_cache(maxsize=None)
    def no_zero_local_factor(x, start):
        if x <= 1:
            return 1
        root = isqrt(x)
        first_tail = max(pi_small[root], start)
        lower = primes[first_tail - 1] if first_tail > pi_small[root] else root
        result = 1 + ways[1] * (prime_pi(x) - prime_pi(lower))
        for idx in range(start, pi_small[root]):
            p = primes[idx]
            if p == 3:
                weights = ways
            elif p % 3 == 1:
                weights = [ways[e] if e % 3 != 2 else 0 for e in range(max_e + 1)]
            else:
                weights = [ways[e] if e % 2 == 0 else 0 for e in range(max_e + 1)]
            power = p
            e = 1
            while power <= x:
                coeff = weights[e]
                if coeff:
                    result += coeff * no_zero_local_factor(x // power, idx + 1)
                e += 1
                if power > x // p:
                    break
                power *= p
        return result % MOD

    return (all_sum - no_zero_local_factor(N, 0)) % MOD

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the specified tiling."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    sk = S_y % K if (si + sj) % 2 == 0 else S_x % K
    tk = T_y % K if (ti + tj) % 2 == 0 else T_x % K
    if (si, sj, sk) == (ti, tj, tk):
        return 0
    span = abs(ti - si) + abs(tj - sj)
    if span > 60:
        return span

    # For small K, retain every lane. For large K only the endpoints that
    # can affect an optimal route are needed.
    lanes = list(range(K)) if K <= 200 else sorted({0, K - 1, sk, tk})
    pad = span + 2
    low_i, high_i = min(si, ti) - pad, max(si, ti) + pad
    low_j, high_j = min(sj, tj) - pad, max(sj, tj) + pad

    dist = {(si, sj, sk): 0}
    heap = [(0, si, sj, sk)]
    while heap:
        d, i, j, k = heappop(heap)
        if d != dist.get((i, j, k)):
            continue
        if (i, j, k) == (ti, tj, tk):
            return d
        for q in lanes:
            nd = d + abs(k - q)
            state = (i, j, q)
            if nd < dist.get(state, 10**100):
                dist[state] = nd
                heappush(heap, (nd, i, j, q))

        horizontal = (i + j) % 2 == 0
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if not (low_i <= ni <= high_i and low_j <= nj <= high_j):
                continue
            if horizontal:
                src_fixed = (K - 1 if dj == 1 else 0) if di == 0 else None
                dst_fixed = (0 if di == 1 else K - 1) if dj == 0 else None
            else:
                src_fixed = (K - 1 if di == 1 else 0) if dj == 0 else None
                dst_fixed = (0 if dj == 1 else K - 1) if di == 0 else None
            if src_fixed is not None and k != src_fixed:
                continue
            for q in lanes:
                if dst_fixed is not None and q != dst_fixed:
                    continue
                state = (ni, nj, q)
                nd = d + 1
                if nd < dist.get(state, 10**100):
                    dist[state] = nd
                    heappush(heap, (nd, ni, nj, q))
    return span

