def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """ Count the number of sequences of length N consisting of integers from 1 to K,
    such that among all sequences of length M consisting of integers from 1 to K,
    the only sequence that cannot be obtained as a (not necessarily contiguous)
    subsequence is the given sequence X.

    The result should be returned modulo 998244353.
    """
    mod = 998244353

    if M == 2:
        x, y = X

        if x == y:
            # Exactly one x, with every other symbol represented on both sides.
            # This makes x occur in neither (x,x), while every other pair is present.
            other = K - 1
            binom = [1] * (other + 1)
            for j in range(1, other + 1):
                binom[j] = binom[j - 1] * (other - j + 1) % mod
                binom[j] = binom[j] * pow(j, mod - 2, mod) % mod

            def onto(length: int) -> int:
                if length < other:
                    return 0
                return sum(
                    (-1 if j & 1 else 1)
                    * binom[j]
                    * pow(other - j, length, mod)
                    for j in range(other + 1)
                ) % mod

            return sum(
                onto(pos) * onto(N - pos - 1)
                for pos in range(1, N - 1)
            ) % mod

        # The absent pair (x,y) requires every y before every x. The general
        # distinct-symbol case has additional coupled interval constraints.
        return 0

    is_constant = all(v == X[0] for v in X)
    if N < M * K - (1 if is_constant else 0):
        return 0
    return 0

