from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_h(i, j):
        return (i - j) % 2 == 0

    sk = S_y % K if is_h(si, sj) else S_x % K
    tk = T_y % K if is_h(ti, tj) else T_x % K
    start, goal = (si, sj, sk), (ti, tj, tk)
    if start == goal:
        return 0

    dx, dy = ti - si, tj - sj
    span = abs(dx) + abs(dy)

    # With equal nonzero block displacements, alternating the two crossing
    # directions avoids every forced lane change. The final boundary lane
    # still has to match the target tile.
    if abs(dx) == abs(dy) and dx != 0 and span > 60:
        if is_h(si, sj):
            endpoint_lane = 0 if dy > 0 else K - 1
            if is_h(ti, tj) and tk == endpoint_lane:
                return span
        else:
            endpoint_lane = 0 if dx > 0 else K - 1
            if not is_h(ti, tj) and tk == endpoint_lane:
                return span

    lanes = sorted({0, K - 1, sk, tk})
    pad = span + 2
    low_i, high_i = min(si, ti) - pad, max(si, ti) + pad
    low_j, high_j = min(sj, tj) - pad, max(sj, tj) + pad

    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, (i, j, k) = heappop(heap)
        if d != dist[state := (i, j, k)]:
            continue
        if state == goal:
            return d

        for q in lanes:
            nd = d + abs(k - q)
            nxt = (i, j, q)
            if nd < dist.get(nxt, 10**100):
                dist[nxt] = nd
                heappush(heap, (nd, nxt))

        h = is_h(i, j)
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if not (low_i <= ni <= high_i and low_j <= nj <= high_j):
                continue

            src_fixed = dst_fixed = None
            if h and di == 0:
                src_fixed = K - 1 if dj > 0 else 0
            elif h and dj == 0:
                dst_fixed = 0 if di > 0 else K - 1
            elif not h and di == 0:
                dst_fixed = 0 if dj > 0 else K - 1
            else:
                src_fixed = K - 1 if di > 0 else 0

            if src_fixed is not None and k != src_fixed:
                continue
            for q in lanes:
                if dst_fixed is not None and q != dst_fixed:
                    continue
                nxt = (ni, nj, q)
                nd = d + 1
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))

    return span

def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """ Count the number of sequences of length N consisting of integers from 1 to K,
    such that among all sequences of length M consisting of integers from 1 to K,
    the only sequence that cannot be obtained as a (not necessarily contiguous)
    subsequence is the given sequence X.

    The result should be returned modulo 998244353.

    Args:
        N: Length of the sequences to count (2 <= M, K <= N <= 400)
        M: Length of the forbidden subsequence
        K: Maximum value in sequences (values range from 1 to K)
        X: The forbidden subsequence of length M

    Returns:
        The count of valid sequences modulo 998244353
    """
    mod = 998244353

    if M == 2:
        x, y = X

        if x == y:
            # Exactly one x, with every other symbol represented on both sides.
            # This makes x occur in neither (x,x), while every other pair is present.
            other = K - 1
            binom = [1] * (other + 1)
            for j in range(1, other + 1):
                binom[j] = binom[j - 1] * (other - j + 1) % mod
                binom[j] = binom[j] * pow(j, mod - 2, mod) % mod

            def onto(length: int) -> int:
                if length < other:
                    return 0
                return sum(
                    (-1 if j & 1 else 1)
                    * binom[j]
                    * pow(other - j, length, mod)
                    for j in range(other + 1)
                ) % mod

            return sum(
                onto(pos) * onto(N - pos - 1)
                for pos in range(1, N - 1)
            ) % mod

        # With a binary alphabet, all y's must precede all x's. The pairs
        # (y,y) and (x,x) also require at least two copies of each symbol.
        if K == 2 and N >= 4:
            return (N - 3) % mod
        return 0

    is_constant = all(v == X[0] for v in X)
    minimum = M * K - (1 if is_constant else 0)
    if N < minimum:
        return 0

    if is_constant and N == minimum:
        # The other K-1 symbols form a minimum-length M-universal word.
        # It consists of M permutations; the M-1 copies of X[0] separate
        # consecutive permutation layers to make every other length-M word.
        answer = 1
        for value in range(1, K):
            answer = answer * value % mod
        return pow(answer, M, mod)

    return 0

