def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N strings over 1..K whose only missing length-M
    subsequence is X, modulo 998244353."""
    mod = 998244353

    def onto(length: int, alphabet_size: int) -> int:
        """Number of length-length strings using every symbol of an alphabet."""
        if alphabet_size == 0:
            return int(length == 0)
        if length < alphabet_size:
            return 0
        choose = 1
        total = 0
        for j in range(alphabet_size + 1):
            term = pow(alphabet_size - j, length, mod)
            total += (-1 if j & 1 else 1) * choose * term
            if j < alphabet_size:
                choose = choose * (alphabet_size - j) % mod
                choose = choose * pow(j + 1, mod - 2, mod) % mod
        return total % mod

    if M == 2:
        x, y = X
        if x == y:
            # x occurs exactly once, between occurrences of every other symbol.
            other = K - 1
            return sum(
                onto(left, other) * onto(N - left - 1, other)
                for left in range(1, N - 1)
            ) % mod

        # Every y is before every x. Let L end at the last y, R start
        # at the first x, and G be the intervening string. Each other symbol
        # must occur in both L and R; the remaining ordered pairs then follow.
        others = K - 2

        def side(length: int) -> int:
            # The final (or initial) character is the distinguished symbol.
            # In the other positions, use every other symbol and at least one
            # additional copy of the distinguished symbol.
            return (onto(length - 1, others + 1) - onto(length - 1, others)) % mod

